#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    // If no argument is provided, treat empty string as palindrome.
    if (argc <= 1) {
        puts("PALINDROME");
        return 0;
    }

    const char *input = argv[1];
    size_t input_len = strlen(input);
    // The original binary rejects strings longer than 1024 characters.
    if (input_len > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    // Build a normalized version: keep only alphanumeric characters, convert letters to lower case.
    char norm[1025]; // enough for the normalized string (max length <= input_len)
    size_t norm_len = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[norm_len++] = (char)tolower(c);
        }
    }
    norm[norm_len] = '\0';

    // Check if the normalized string is a palindrome.
    int is_palindrome = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_palindrome = 0;
            break;
        }
    }

    puts(is_palindrome ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
